command:
tail -20 artifacts/stock-scanner-api/dpl/verified_run_chain.jsonl 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line = line.strip()
    if line:
        try:
            d = json.loads(line)
            print('SEQ:', d.get('seq'), 'ts:', d.get('ts'), 'commit:', d.get('commit'), 'tree:', d.get('tree'), 'pass:', d.get('pass_count'), 'fail:', d.get('fail_count'))
        except:
            print(repr(line[:80]))
"
